use crate::*;
#[derive(Clone,Serialize,Deserialize,Debug)]#[serde(rename_all="camelCase")]pub struct Furniture{#[serde(default)]pub id:String,pub kind:String,pub room_id:String,pub x:f64,pub z:f64,pub w:f64,pub d:f64,pub rotation:f64,pub local_width:f64,pub local_depth:f64}
fn overlap(a:[f64;4],b:[f64;4])->bool{a[0]<b[2]-0.001&&a[2]>b[0]+0.001&&a[1]<b[3]-0.001&&a[3]>b[1]+0.001}
fn rect(f:&Furniture,p:f64)->[f64;4]{[f.x-f.w/2.-p,f.z-f.d/2.-p,f.x+f.w/2.+p,f.z+f.d/2.+p]}
pub fn aprons(r:&Room,ws:&[Wall])->Vec<[f64;4]>{let mut a=vec![];for w in ws{let along=w.axis=="x";let line=if along{w.z}else{w.x};let front=if along{r.z}else{r.x};let back=front+if along{r.d}else{r.w};if !near(line,front)&&!near(line,back){continue}for o in w.openings.iter().filter(|o|o.kind!="window"){let at=(if along{w.x}else{w.z})+o.at;let lo=at-0.35;let hi=at+o.width+0.35;let far=if near(line,front){line+2.8}else{line-2.8};a.push(if along{[lo,line.min(far),hi,line.max(far)]}else{[line.min(far),lo,line.max(far),hi]});}}a}
thread_local!{static BLOCKED:std::cell::RefCell<Vec<[f64;4]>>=const{std::cell::RefCell::new(Vec::new())};}
// Accessibility zones (stair approaches, turning circles) are known while staging so an item that
// would land in one moves on to its next spot instead of being dropped afterwards.
pub fn build_clear_of(rs:&[Room],ws:&[Wall],zones:&[[f64;4]])->(Vec<Furniture>,Vec<String>){BLOCKED.with(|b|*b.borrow_mut()=zones.to_vec());let out=build(rs,ws);BLOCKED.with(|b|b.borrow_mut().clear());out}
fn place(out:&mut Vec<Furniture>,r:&Room,ws:&[Wall],kind:&str,lw:f64,ld:f64,clear:f64,center:bool)->bool{place_after(out,r,ws,kind,lw,ld,clear,center,0)}
fn place_after(out:&mut Vec<Furniture>,r:&Room,ws:&[Wall],kind:&str,lw:f64,ld:f64,clear:f64,center:bool,mut skip:usize)->bool{let apr=aprons(r,ws);let mut candidates=vec![];if center{if kind=="coffee"{if let Some(sofa)=out.iter().find(|f|f.room_id==r.id&&f.kind=="sofa"){let distance=sofa.local_depth/2.+ld/2.+1.8;candidates.push((sofa.x-sofa.rotation.sin()*distance,sofa.z+sofa.rotation.cos()*distance,(sofa.rotation/std::f64::consts::FRAC_PI_2).round()as usize));}}else{let long_x=r.w>=r.d;for off in [0.,1.,-1.,2.,-2.,3.,-3.,4.,-4.]{let(x,z)=if long_x{(r.x+r.w/2.+off,r.z+r.d/2.)}else{(r.x+r.w/2.,r.z+r.d/2.+off)};candidates.push((x,z,0));candidates.push((x,z,1));}}}else{for side in 0..4{let len=if side%2==0{r.w}else{r.d};if len<lw+0.7{continue}let mut offsets=vec![len/2.];let mut at=lw/2.+0.4;while at<len-lw/2.-0.3{offsets.push(at);at+=0.5;}for at in offsets{let(x,z)=match side{0=>(r.x+at,r.z+ld/2.+0.35),1=>(r.x+r.w-ld/2.-0.35,r.z+at),2=>(r.x+at,r.z+r.d-ld/2.-0.35),_=>(r.x+ld/2.+0.35,r.z+at)};candidates.push((x,z,side));}}}if kind=="nightstand"{if let Some(bed)=out.iter().find(|f|f.room_id==r.id&&f.kind=="bed"){let side=(bed.rotation/std::f64::consts::FRAC_PI_2).round()as usize;let dz=-bed.local_depth/2.+ld/2.;let mut near_bed=vec![];for sign in [-1.,1.]{let dx=sign*(bed.local_width/2.+lw/2.+0.6);near_bed.push((bed.x+bed.rotation.cos()*dx-bed.rotation.sin()*dz,bed.z+bed.rotation.sin()*dx+bed.rotation.cos()*dz,side));}candidates=near_bed;}}
if kind=="console"{if let Some(sofa)=out.iter().find(|f|f.room_id==r.id&&f.kind=="sofa"){let side=((sofa.rotation/std::f64::consts::FRAC_PI_2).round()as usize+2)%4;let(x,z)=match side{0=>(sofa.x,r.z+ld/2.+0.35),1=>(r.x+r.w-ld/2.-0.35,sofa.z),2=>(sofa.x,r.z+r.d-ld/2.-0.35),_=>(r.x+ld/2.+0.35,sofa.z)};candidates.insert(0,(x,z,side));}}
for(x,z,side)in candidates{let(w,d)=if side%2==0{(lw,ld)}else{(ld,lw)};let base_id=format!("F-{}-{}",r.id,kind);let id=if out.iter().any(|q|q.id==base_id){(2..).map(|i|format!("{}-{}",base_id,i)).find(|c|!out.iter().any(|q|&q.id==c)).unwrap()}else{base_id};let f=Furniture{id,kind:kind.into(),room_id:r.id.clone(),x,z,w,d,rotation:side as f64*std::f64::consts::FRAC_PI_2,local_width:lw,local_depth:ld};let a=rect(&f,0.);let mut use_a=a;if !center{match side{0=>use_a[3]+=clear,1=>use_a[0]-=clear,2=>use_a[1]-=clear,_=>use_a[2]+=clear}}else{for i in 0..4{use_a[i]+=if i<2{-clear}else{clear};}}if use_a[0]<r.x+0.25||use_a[1]<r.z+0.25||use_a[2]>r.x+r.w-0.25||use_a[3]>r.z+r.d-0.25||apr.iter().any(|b|overlap(a,*b))||BLOCKED.with(|b|b.borrow().iter().any(|z|overlap(a,*z)))||out.iter().filter(|q|q.room_id==r.id).any(|q|overlap(use_a,rect(q,0.45))){continue}if !center{let along=side%2==0;let line=match side{0=>r.z,1=>r.x+r.w,2=>r.z+r.d,_=>r.x};let lo=if along{x-lw/2.}else{z-lw/2.};let hi=lo+lw;let backed=ws.iter().any(|wall|wall.axis==if along{"x"}else{"z"}&&near(if along{wall.z}else{wall.x},line)&&{let start=if along{wall.x}else{wall.z};start<=lo+0.01&&start+wall.length>=hi-0.01&&!wall.openings.iter().any(|o|(o.kind!="window"||["fridge","wardrobe","wallbed","console","bookcase","dresser","pantry-tower"].contains(&kind))&&lo<start+o.at+o.width+0.2&&hi>start+o.at-0.2)});if !backed{continue}}if !edit::clear_of_walls(&f,ws){continue}if skip>0{skip-=1;continue}out.push(f);return true}false}
pub fn build(rs:&[Room],ws:&[Wall])->(Vec<Furniture>,Vec<String>){let mut f=vec![];let mut notes=vec![];for r in rs{match r.kind.as_str(){"bedroom"=>{let mut fit=false;for bw in [5.,4.5,3.25]{if place(&mut f,r,ws,"bed",bw,6.7,2.5,false){fit=true;break}}if !fit{notes.push(format!("{} needs room/opening changes to fit a bed with a clear approach.",r.name));}place(&mut f,r,ws,"nightstand",1.3,1.3,0.,false);place(&mut f,r,ws,"wardrobe",3.,2.,2.,false);},"kitchen"=>{stage_kitchen(&mut f,r,ws);if !rs.iter().any(|q|q.kind=="dining")&&r.w.min(r.d)>=10.&&r.w*r.d>=200.{for(w,d,clear)in[(6.,5.5,2.),(4.,5.,1.25),(3.,4.5,0.75)]{if place(&mut f,r,ws,"dining",w,d,clear,true){break}}}},"bath"=>{stage_bath(&mut f,r,ws);},"studio"=>{place(&mut f,r,ws,"wallbed",r.w.min(r.d).min(7.)-1.,1.1,3.,false);if !rs.iter().any(|q|q.kind=="kitchen"){for len in [6.,4.,3.]{if place(&mut f,r,ws,"kitchen",len,2.,2.5,false){break}}}if r.w>13.&&r.d>13.{place(&mut f,r,ws,"sofa",5.,2.8,3.,false);}},"living"=>{for len in [8.,6.,4.5]{if place(&mut f,r,ws,"sofa",len,2.8,3.,false){break}}place(&mut f,r,ws,"coffee",3.5,2.,1.2,true);place(&mut f,r,ws,"console",4.,1.2,2.,false);if !rs.iter().any(|q|q.kind=="dining")&&r.w>=20.&&r.d>=12.{place(&mut f,r,ws,"dining",6.,5.5,2.,true);}if r.w>=16.&&r.d>=12.{place(&mut f,r,ws,"armchair",2.7,2.7,2.,false);}},"dining"=>{for(w,d,clear)in[(6.,5.5,2.),(4.,5.,1.25),(3.,4.5,0.75)]{if place(&mut f,r,ws,"dining",w,d,clear,true){break}}},"flex"=>{if r.name.to_lowercase().contains("pantry"){for len in [10.,8.,6.,4.]{if place(&mut f,r,ws,"counter-run",len,2.,3.,false){break}}for _ in 0..2{place(&mut f,r,ws,"pantry-tower",2.5,2.,3.,false);}}else if r.name.to_lowercase().contains("laundry"){if !place(&mut f,r,ws,"laundry",5.,2.5,3.,false){place(&mut f,r,ws,"laundry",2.7,2.7,2.5,false);}}else if r.name.contains("Family")||r.name.contains("lounge"){place(&mut f,r,ws,"sofa",5.,2.8,3.,false);}else{for(w,d,clear)in[(4.,2.,2.5),(3.,1.8,2.),(2.5,1.6,1.5)]{if place(&mut f,r,ws,"desk",w,d,clear,false){break}}}},_=>{}}if ["living","flex"].contains(&r.kind.as_str())&&r.w>=12.&&r.d>=12.{place(&mut f,r,ws,"floorlamp",1.6,1.6,0.,false);place(&mut f,r,ws,"bookcase",3.,1.1,1.5,false);}if r.kind=="bedroom"&&r.w>=12.&&r.d>=14.{place(&mut f,r,ws,"bench",4.,1.6,1.5,false);}if r.kind=="dining"&&r.w>=12.&&r.d>=12.{place(&mut f,r,ws,"sideboard",5.,1.7,2.,false);}if r.kind=="bedroom"&&r.w>=14.&&r.d>=12.{place(&mut f,r,ws,"dresser",5.,1.7,2.,false);}if r.kind=="foyer"&&r.w.max(r.d)>=6.&&r.w.min(r.d)>=4.{if !place(&mut f,r,ws,"storage-bench",4.,1.6,1.5,false){place(&mut f,r,ws,"storage-bench",3.,1.4,1.,false);}place(&mut f,r,ws,"coat-stand",1.8,1.8,0.,false);}if r.kind=="bath"&&r.w>=8.&&r.d>=10.{place(&mut f,r,ws,"linen-cabinet",2.,1.2,1.5,false);}if r.kind!="hall"&&r.kind!="stairs"&&r.w>=9.&&r.d>=9.{place(&mut f,r,ws,"plant",1.3,1.3,0.,false);}}(f,notes)}

// A full kitchen: the longest sink-and-range run the walls allow, the refrigerator, more counter runs on
// the other walls (L- and U-shaped kitchens), tall pantry cabinets and an island where the room has space.
fn stage_kitchen(out:&mut Vec<Furniture>,r:&Room,ws:&[Wall]){
 let run=|out:&mut Vec<Furniture>|{for len in [16.,14.,12.,10.,8.,6.,4.]{if place(out,r,ws,"kitchen",len,2.5,3.5,false){return true}}false};
 let fridge=|out:&mut Vec<Furniture>|place(out,r,ws,"fridge",3.,2.7,3.5,false)||place(out,r,ws,"fridge",2.7,2.5,3.,false);
 let start=out.clone();let a=run(out);let b=fridge(out);
 if !(a&&b){let mut alt=start.clone();if fridge(&mut alt)&&run(&mut alt){*out=alt;}}
 for len in [12.,10.,8.,6.,5.,4.]{if place(out,r,ws,"counter-run",len,2.,3.5,false){break}}
 for _ in 0..2{place(out,r,ws,"pantry-tower",2.5,2.,3.,false);}
 if r.w>=12.&&r.d>=12.{for(w,d)in[(8.,4.),(7.,3.5),(6.,3.5),(5.,3.)]{if place(out,r,ws,"island",w,d,3.5,true){break}}}
 if r.w*r.d>=180.{for len in [10.,8.,6.,5.,4.]{if place(out,r,ws,"counter-run",len,2.,3.5,false){break}}}
}

// Search fixture arrangements together instead of letting the first shower
// block the toilet and basin in a compact bathroom. Clear approaches may share
// floor space, but fixture bodies and doorway approaches never overlap.
fn stage_bath(out:&mut Vec<Furniture>,r:&Room,ws:&[Wall]){
 let powder=r.name.to_lowercase().contains("powder");let original=out.clone();
 for shower_skip in 0..if powder{1}else{24}{let mut trial=original.clone();if !powder&&!place_after(&mut trial,r,ws,"shower",3.,3.,2.,false,shower_skip){break}
  for toilet_skip in 0..24{let mut complete=trial.clone();if !place_after(&mut complete,r,ws,"toilet",2.5,2.5,2.,false,toilet_skip){break}if place(&mut complete,r,ws,"vanity",2.5,2.,2.,false){*out=complete;return}}
 }
 if !powder{place(out,r,ws,"shower",3.,3.,2.,false);}place(out,r,ws,"toilet",2.5,2.5,2.,false);place(out,r,ws,"vanity",2.5,2.,2.,false);
}
